--[[
  VEXIS LUA PROTECTOR 2.1
  Level: ADVANCED
  Modo: SCRIPT LUA — se ejecuta con loadstring
  Compatible con: Delta, Fluxus, Synapse, Hydrogen y otros executors
]]

local VEXIS_LEVEL = "advanced"
local VEXIS_CHECKSUM = "c9c21774"
local VEXIS_DATA = [[]]

local BASE64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function reverseTransform(data, level)
    if level == "medium" then
        return data:reverse()
    elseif level == "advanced" then
        local result = {}
        for i = 1, #data do
            local c = data:sub(i, i)
            local idx = BASE64_CHARS:find(c, 1, true)
            if idx then
                result[i] = BASE64_CHARS:sub(((idx - 1 - 7) % 64) + 1, ((idx - 1 - 7) % 64) + 1)
            else
                result[i] = c
            end
        end
        return table.concat(result)
    end
    return data
end

local function decodeBase64(data)
    local result, buffer, bits = {}, 0, 0
    data = data:gsub("[^ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=]", "")
    for i = 1, #data do
        local char = data:sub(i, i)
        if char == "=" then break end
        local value = BASE64_CHARS:find(char, 1, true)
        if not value then error("VEXIS: caracter Base64 invalido en posicion " .. i) end
        buffer = buffer * 64 + value - 1
        bits = bits + 6
        if bits >= 8 then
            bits = bits - 8
            local divisor = 2 ^ bits
            result[#result + 1] = string.char(math.floor(buffer / divisor) % 256)
            buffer = buffer % divisor
        end
    end
    return table.concat(result)
end

local function calculateChecksum(source)
    local sum = 0
    for i = 1, #source do
        sum = (sum + string.byte(source, i) * (((i - 1) % 65521) + 1)) % 4294967296
    end
    return string.format("%08x", sum)
end

local transformed = reverseTransform(VEXIS_DATA, VEXIS_LEVEL)
local source = decodeBase64(transformed)

if calculateChecksum(source) ~= VEXIS_CHECKSUM then
    error("VEXIS: verificacion de integridad fallida — el archivo fue modificado")
end

if type(loadstring) ~= "function" then
    error("VEXIS: loadstring no disponible en este entorno")
end

local chunk, compileError = loadstring(source)
if type(chunk) ~= "function" then
    error("VEXIS: error de compilacion — " .. tostring(compileError))
end

local ok, runtimeResult = pcall(chunk)
if not ok then
    error("VEXIS: error al ejecutar — " .. tostring(runtimeResult))
end

return runtimeResult
